// Collects the seven sources into one compact object. A failed source just becomes {ok:false}.
const get = (name) => { try { const j = $(name).first().json; return j && !j.error ? j : null; } catch (e) { return null; } };
// who started this run: the 6-hour schedule, a visitor (webhook from the site) or the CLI
let started = Date.now(), by = 'manual';
try { started = Date.parse($('Alle 6 Stunden').first().json.timestamp) || started; by = 'schedule'; } catch (e) {}
try { const w = $('Besucher-Knopf (Webhook)').first().json; started = (w.body && w.body.t) || started; by = 'visitor'; } catch (e) {}
const s = {};

let j = get('ISS-Position');
s.iss = j && j.latitude !== undefined ? { ok: true, lat: j.latitude, lon: j.longitude, alt: j.altitude, vel: j.velocity } : { ok: false };

j = get('Erdbeben (USGS)');
if (j && Array.isArray(j.features)) {
  const top = j.features.map(f => ({ mag: f.properties.mag, place: f.properties.place, time: f.properties.time, url: f.properties.url,
    lon: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] })).sort((a, b) => b.mag - a.mag).slice(0, 15);
  s.quakes = { ok: true, count: j.features.length, top };
} else s.quakes = { ok: false };

j = get('Hacker News');
if (j && Array.isArray(j.hits) && j.hits.length) {
  const h = [...j.hits].sort((a, b) => (b.points || 0) - (a.points || 0))[0];
  s.hn = { ok: true, title: h.title, url: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID), points: h.points, comments: h.num_comments,
    hn: 'https://news.ycombinator.com/item?id=' + h.objectID };
} else s.hn = { ok: false };

j = get('Wikipedia meistgelesen');
const arts = j && j.mostread && Array.isArray(j.mostread.articles) ? j.mostread.articles.filter(a => !/^(Wikipedia|Spezial|Datei|Hilfe):/.test(a.title) && a.title !== 'Wikipedia:Hauptseite') : [];
s.wiki = arts.length ? { ok: true, title: arts[0].normalizedtitle || arts[0].title, views: arts[0].views, url: arts[0].content_urls.desktop.page, extract: arts[0].extract } : { ok: false };

j = get('Wetter am Server (Berlin)');
s.weather = j && j.current ? { ok: true, temp: j.current.temperature_2m, wind: j.current.wind_speed_10m, code: j.current.weather_code, day: !!j.current.is_day } : { ok: false };

j = get('Status-Monitor (eigene Seite)');
if (j && j.services) {
  const v = Object.entries(j.services);
  s.status = { ok: true, total: v.length, up: v.filter(([k, x]) => x.state === 'ok').length, bad: v.filter(([k, x]) => x.state === 'problem').map(([k]) => k) };
} else s.status = { ok: false };

j = get('GitHub: n8n');
s.github = j && j.stargazers_count ? { ok: true, stars: j.stargazers_count, forks: j.forks_count } : { ok: false };

const q = s.quakes.ok && s.quakes.top[0];
const facts = {
  iss: s.iss.ok ? `ISS at ${s.iss.lat.toFixed(1)}, ${s.iss.lon.toFixed(1)}, ${Math.round(s.iss.vel)} km/h` : null,
  quake: q ? `strongest quake in 24h: M${q.mag} ${q.place}; ${s.quakes.count} quakes M2.5+ in 24h` : null,
  hackernews: s.hn.ok ? `top on Hacker News: "${s.hn.title}" (${s.hn.points} points)` : null,
  wikipedia: s.wiki.ok ? `most read on German Wikipedia yesterday: "${s.wiki.title}" (${s.wiki.views} views)` : null,
  weather_berlin: s.weather.ok ? `${s.weather.temp} °C, wind ${s.weather.wind} km/h` : null,
  status_monitor: s.status.ok ? `${s.status.up} of ${s.status.total} monitored services reachable` : null,
  n8n_github_stars: s.github.ok ? s.github.stars : null,
};
const prompt = 'You are the cheerful on-air voice of a tiny robot radio station that lives inside an n8n workflow on a server in Berlin. '
  + 'From the live facts below write ONE short bulletin of 2 sentences (max 240 characters) in German, English and Italian. Pick 2 or 3 facts, keep every number exactly as given, invent nothing. '
  + 'Be playful and warm. If a fact is about death, disaster, war or violence, mention it neutrally without any joke, or skip it. Answer with JSON only: {"de":"","en":"","it":""}\n\nFACTS:\n'
  + JSON.stringify(facts);
return [{ json: { started, by, sources: s, body: { model: 'openai/gpt-oss-120b', temperature: 0.7, max_tokens: 1500, response_format: { type: 'json_object' },
  messages: [{ role: 'user', content: prompt }] } } }];

// Reads the AI answer; if the model failed, a plain bulletin is built from the data so the page never stays empty.
const data = $('Daten bündeln').first().json;
let b = null;
try {
  const raw = $input.first().json.choices[0].message.content;
  const m = String(raw).match(/\{[\s\S]*\}/);
  b = JSON.parse(m[0]);
  if (!b.de || !b.en || !b.it) b = null;
} catch (e) { b = null; }
if (!b) {
  const s = data.sources;
  const p = s.status.ok ? `${s.status.up}/${s.status.total}` : '?';
  b = { de: `Puls gemessen: ${p} Dienste erreichbar` + (s.iss.ok ? `, die ISS rast mit ${Math.round(s.iss.vel)} km/h.` : '.'),
        en: `Pulse taken: ${p} services reachable` + (s.iss.ok ? `, the ISS is racing along at ${Math.round(s.iss.vel)} km/h.` : '.'),
        it: `Polso misurato: ${p} servizi raggiungibili` + (s.iss.ok ? `, la ISS corre a ${Math.round(s.iss.vel)} km/h.` : '.') };
}
return [{ json: { by: data.by, sources: data.sources, bulletin: b, ms: Date.now() - data.started } }];
